-- 0004: atomic checkout
--
-- One function that saves an order and takes its stock in a single transaction.
-- Either the order is saved AND the stock is reduced, or nothing happens.
--
-- It also fixes two things the browser used to decide:
--   * prices come from the menu, not from the cart the browser sends
--   * org_id and staff_id come from the shift and the login, not the browser
--
-- p_order_id is generated by the browser once per checkout. If the connection
-- drops after the order was saved and the cashier taps again, the same id comes
-- back and the saved order is returned instead of a second order being created.

create function public.place_order(
  p_order_id        uuid,
  p_shift_id        uuid,
  p_items           jsonb,            -- [{ "item_id": "...", "qty": 2 }, ...]
  p_payment_method  text,             -- 'cash' | 'transfer' | 'split'
  p_amount_received numeric default null,  -- cash only
  p_cash_amount     numeric default 0,     -- split only
  p_transfer_amount numeric default 0,     -- split only
  p_expected_total  numeric default null   -- the total the cashier saw
)
returns public.orders
language plpgsql security definer set search_path = ''
as $$
declare
  v_user     uuid := (select auth.uid());
  v_org      uuid;
  v_existing public.orders;
  v_wanted   integer;
  v_found    integer;
  v_items    jsonb;
  v_total    numeric;
  v_cash     numeric := 0;
  v_transfer numeric := 0;
  v_change   numeric := 0;
  v_have     integer;
  v_short    text[]  := '{}';
  r          record;
  v_order    public.orders;
begin
  if v_user is null then
    raise exception 'You must be signed in';
  end if;

  -- a retry of an order that already went through: hand back the saved order
  select * into v_existing from public.orders where id = p_order_id and staff_id = v_user;
  if found then
    return v_existing;
  end if;

  -- the shift must be open, and the caller must belong to its business
  select s.org_id into v_org from public.shifts s where s.id = p_shift_id and s.closed_at is null;
  if v_org is null or not public.is_org_member(v_org) then
    raise exception 'This shift is closed, so the order was not saved';
  end if;

  if jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'The order has no items';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_items) e
    where coalesce((e->>'qty')::integer, 0) < 1
  ) then
    raise exception 'Every item needs a quantity of at least 1';
  end if;

  -- price every line from the menu (same item twice is merged into one line)
  select count(distinct (e->>'item_id')::uuid) into v_wanted from jsonb_array_elements(p_items) e;

  select count(*),
         sum(m.price * l.qty),
         jsonb_agg(jsonb_build_object(
           'item_id',    m.id,
           'name',       m.name,
           'qty',        l.qty,
           'unit_price', m.price,
           'subtotal',   m.price * l.qty
         ) order by m.name)
    into v_found, v_total, v_items
    from (
      select (e->>'item_id')::uuid as item_id, sum((e->>'qty')::integer) as qty
      from jsonb_array_elements(p_items) e
      group by 1
    ) l
    join public.menu_items m on m.id = l.item_id and m.org_id = v_org and m.available;

  if v_found is distinct from v_wanted then
    raise exception 'An item in this order is no longer available. Clear the order and add the items again';
  end if;

  if p_expected_total is not null and p_expected_total <> v_total then
    raise exception 'Prices changed while you were checking out. The total is now ₦%. Clear the order and add the items again', v_total;
  end if;

  -- payment
  if p_payment_method = 'cash' then
    if p_amount_received is null or p_amount_received < v_total then
      raise exception 'The amount received is less than the total';
    end if;
    v_cash   := v_total;
    v_change := p_amount_received - v_total;
  elsif p_payment_method = 'transfer' then
    v_transfer := v_total;
  elsif p_payment_method = 'split' then
    if p_cash_amount < 0 or p_transfer_amount < 0 or p_cash_amount + p_transfer_amount <> v_total then
      raise exception 'Cash and transfer must add up to the total';
    end if;
    v_cash     := p_cash_amount;
    v_transfer := p_transfer_amount;
  else
    raise exception 'Unknown payment method';
  end if;

  -- lock the stock rows in a fixed order (so two checkouts can't deadlock),
  -- and collect every shortage so the cashier sees them all at once
  for r in
    select x.item_id, x.name, x.qty
    from jsonb_to_recordset(v_items) as x(item_id uuid, name text, qty integer, unit_price numeric, subtotal numeric)
    order by x.item_id
  loop
    select ss.quantity into v_have
    from public.shift_stock ss
    where ss.shift_id = p_shift_id and ss.item_id = r.item_id
    for update;

    if v_have is null or v_have < r.qty then
      v_short := v_short || case
        when coalesce(v_have, 0) = 0 then r.name || ' is out of stock'
        else r.name || ': only ' || v_have || ' left'
      end;
    end if;
  end loop;

  if array_length(v_short, 1) is not null then
    raise exception 'Not enough stock. %', array_to_string(v_short, '. ');
  end if;

  -- take the stock
  update public.shift_stock ss
     set quantity = ss.quantity - x.qty
    from jsonb_to_recordset(v_items) as x(item_id uuid, name text, qty integer, unit_price numeric, subtotal numeric)
   where ss.shift_id = p_shift_id and ss.item_id = x.item_id;

  -- save the order
  insert into public.orders (
    id, org_id, shift_id, staff_id, items_json, subtotal, total,
    payment_method, cash_amount, transfer_amount, change_given
  ) values (
    p_order_id, v_org, p_shift_id, v_user, v_items, v_total, v_total,
    p_payment_method, v_cash, v_transfer, v_change
  )
  returning * into v_order;

  return v_order;
end;
$$;

revoke all on function public.place_order(uuid, uuid, jsonb, text, numeric, numeric, numeric, numeric) from public, anon;
grant execute on function public.place_order(uuid, uuid, jsonb, text, numeric, numeric, numeric, numeric) to authenticated, service_role;
